(() => {
'use strict';
const $=id=>document.getElementById(id);let tab='map',item='potion',dialogue=null;const keeper=new Image();let keeperRects=[];
const g=()=>window.gameDebug;
const classes=['Следопыт','Волшебник','Воин'];
function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;return b}
function switchTab(next){tab=next;for(const name of['map','hero','bag','test']){$(name+'-view').hidden=name!==tab;$('tab-'+name).classList.toggle('active',name===tab);$('tab-'+name).setAttribute('aria-selected',String(name===tab))}if(tab!=='map')$('title').textContent='Визуальный полигон';else g().render();renderViews()}
function selectHero(step){if(g().busy||g().state.combat)return;const s=g().state,alive=s.party.filter(p=>p.hp>0);if(!alive.length)return;const i=alive.findIndex(p=>p.id===s.active);s.active=alive[(i+step+alive.length)%alive.length].id;g().save();g().render()}
function paintHero(){const s=g().state,a=g().active();$('hero-name').textContent=a.name;$('hero-class').textContent=classes[a.kind];$('hero-level').textContent='Уровень '+s.level;$('hero-art').replaceChildren(g().art(a.kind*4));const threshold=DND.xp[s.level]||Infinity,percent=Math.min(100,Math.max(0,(s.xp-DND.xp[s.level-1])/(threshold-DND.xp[s.level-1])*100));$('hero-progress').innerHTML='<div><span>Опыт</span><div class="hp-track"><i style="width:'+percent+'%"></i></div><b>'+s.xp+' / '+threshold+'</b></div><div><span>Здоровье</span><div class="hp-track"><i style="width:'+a.hp/a.max*100+'%"></i></div><b>'+a.hp+' / '+a.max+'</b></div>';
$('hero-stats').innerHTML=Object.entries(a.stats).map(([key,value])=>'<div><small>'+DND.labels[key]+'</small><b>'+value+'</b><span>'+(DND.mod(value)>=0?'+':'')+DND.mod(value)+'</span></div>').join('');$('equipment').replaceChildren();if(a.kind===0){for(const weapon of[{id:'bow',label:'Лук',icon:'🏹',range:30,damage:8},{id:'sword',label:'Короткий меч',icon:'⚔',range:1,damage:6}]){const b=button('',()=>{if(g().state.combat&&a.acted)return;a.weapon=weapon.id;a.range=weapon.range;a.damage=weapon.damage;g().save();g().render()});b.innerHTML='<b>'+weapon.label+'</b><small>'+weapon.range+' кл. · d'+weapon.damage+' +'+DND.mod(a.stats.dex)+'</small>';const icon=g().art(weapon.id==='bow'?31:32,'portrait');icon.className='item-art';b.prepend(icon);b.className='gear '+((a.weapon||'sword')===weapon.id?'equipped':'');b.disabled=g().busy||(s.combat&&a.acted);$('equipment').append(b)}}else{const b=document.createElement('div');b.className='gear equipped';b.innerHTML='<b>'+(a.kind===1?'Посох · луч':'Меч и щит')+'</b><small>'+DND.weapon(a,s.level).range+' кл. · '+(DND.weapon(a,s.level).count||1)+'d'+DND.weapon(a,s.level).die+' +'+DND.weapon(a,s.level).damageBonus+'</small>';const icon=g().art(a.kind===1?33:32,'portrait');icon.className='item-art';b.prepend(icon);$('equipment').append(b)}
$('level-up').textContent=s.xp>=threshold?'⇧ Повысить уровень':'⇧ Повысить уровень · ещё '+(threshold-s.xp)+' опыта';$('level-up').disabled=s.xp<threshold||g().busy||s.combat;$('hero-action-note').textContent=s.combat?'В бою повышение уровня недоступно. Сменить оружие можно перед атакой.':'КД '+a.ac+' · владение +'+DND.pb(s.level)+' · ячейки '+a.slots+'/'+a.maxSlots+' · кости здоровья '+a.hitDice+'/'+a.maxHitDice}
function levelUp(){const s=g().state;if(s.combat||s.xp<(DND.xp[s.level]||Infinity)||g().busy)return;s.level++;for(const a of s.party){const gain=Math.floor(a.hitDie/2)+1+DND.mod(a.stats.con);a.max+=gain;if(a.hp>0)a.hp=a.max;a.maxHitDice=s.level;a.hitDice++;if(a.kind===1){a.maxSlots=s.level===2?3:4;a.slots=a.maxSlots;}if(s.level===4){a.stats[a.kind===1?'int':a.kind===0?'dex':'str']=Math.min(20,a.stats[a.kind===1?'int':a.kind===0?'dex':'str']+2);}}g().tell('Отряд достиг уровня '+s.level+'. Здоровье увеличено по кости класса и модификатору Телосложения.');g().render()}
function items(){const s=g().state;return[{id:'potion',name:'Лечебное зелье',icon:'⚗',amount:s.potions,category:'Расходуемое',description:'Восстанавливает 2d4 + 2 HP выбранному герою. В бою расходует бонусное действие.'},{id:'coins',name:'Монеты',icon:'◉',amount:s.gold,category:'Валюта',description:'Найденные в часовне монеты. Сохраняются вместе с прогрессом отряда.'},...(s.chest?[{id:'letter',name:'Письмо',icon:'▤',amount:1,category:'Зацепка',description:'«Колокол увезли на север. Не верьте настоятелю». Слова подтверждают след, о котором говорит хранительница.'}]:[]),...(s.relic?[{id:'relic',name:'Язычок колокола',icon:'♮',amount:1,category:'Реликвия',description:'Серебряный язычок исчезнувшего колокола. Найден на алтаре часовни. Связан с её хранительницей Эллен.'}]:[])]}
function paintBag(){const list=items(),selected=list.find(i=>i.id===item)||list[0];item=selected.id;$('bag-gold').textContent=g().state.gold+' монет';$('bag-items').replaceChildren();for(const it of list){const b=button('',()=>{item=it.id;paintBag()});b.className='bag-item '+(item===it.id?'selected':'');b.innerHTML='<b>'+it.name+'</b><small>×'+it.amount+'</small>';const icon=g().art(({potion:34,coins:35,letter:36,relic:18})[it.id],'portrait');icon.className='item-art';b.prepend(icon);$('bag-items').append(b)}$('item-detail').innerHTML='<span class="item-category">'+selected.category+'</span><div id="item-icon" class="item-icon"></div><h2>'+selected.name+'</h2><p>'+selected.description+'</p><div id="item-actions" class="options"></div>';document.getElementById('item-icon').append(g().art(({potion:34,coins:35,letter:36,relic:18})[selected.id],'portrait'));if(selected.id==='potion'){const b=button('Выпить · '+g().active().name,()=>g().potion());b.disabled=$('potion').disabled;$('item-actions').append(b);if(g().active().hp>=g().active().max){const p=document.createElement('p');p.className='subtle';p.textContent='У выбранного героя полное здоровье.';$('item-detail').append(p)}}if(['letter','relic'].includes(selected.id))$('item-actions').append(button('Открыть хронику',()=>g().journal()))}
function renderViews(){if(!g())return;if(tab==='hero'){paintHero();$('title').textContent='Визуальный полигон'}if(tab==='test')window.renderTests?.();if(tab==='bag'){paintBag();$('title').textContent='Визуальный полигон'}if(dialogue)paintDialogue()}
function drawKeeper(c,mode='portrait'){const miniature=mode==='prop';c.width=miniature?128:256;c.height=miniature?160:320;const cx=c.getContext('2d');cx.clearRect(0,0,c.width,c.height);cx.setTransform(miniature?.5:1,0,0,miniature?.5:1,0,0);const r=keeperRects[mode==='portrait'?0:1];if(!r)return;const scale=mode==='prop'?Math.min(184/r.w,250/r.h):Math.min(230/r.w,305/r.h),w=r.w*scale,h=r.h*scale;cx.drawImage(keeper,r.sx,r.sy,r.w,r.h,128-w/2,mode==='prop'?320/1.45-h*.81:160-h/2,w,h)}
function keeperCanvas(){if(window.voxel?.ready){const m=window.voxel.portrait(5);if(m)return m}const c=document.createElement('canvas');c.className='sprite';drawKeeper(c);return c}
function dialogueLine(text,options,name='Эллен · хранительница',portrait=true){dialogue={text,options,name,portrait};paintDialogue()}
function paintDialogue(){if(!dialogue)return;$('dialogue').hidden=false;document.getElementById('map-view').classList.add('dialogue-open');$('speaker-name').textContent=dialogue.name;$('dialogue-text').textContent=dialogue.text;$('speaker-art').replaceChildren();if(dialogue.portrait)$('speaker-art').append(keeperCanvas());else{const mark=document.createElement('span');mark.className='narrator-mark';mark.textContent='◇';$('speaker-art').append(mark)}$('dialogue-options').replaceChildren();for(const option of dialogue.options)$('dialogue-options').append(button(option.label,option.fn))}
function closeDialogue(){dialogue=null;$('dialogue').hidden=true;document.getElementById('map-view').classList.remove('dialogue-open')}
function recordReply(question,response){g().tell('Вы: «'+question+'» Эллен: «'+response+'»');g().render();dialogueLine(response,[{label:'Задать другой вопрос',fn:openKeeper},{label:'Закончить разговор',fn:closeDialogue}])}
function openKeeper(){switchTab('map');dialogueLine('Добро пожаловать в моё ателье. Здесь можно спокойно проверить предметы, потренироваться и подготовиться к следующему путешествию.',[
{label:'Расскажи об этом месте?',fn:()=>{const s=g().state;s.clues=s.clues||[];if(!s.clues.includes('courier'))s.clues.push('courier');recordReply('Расскажи об этом месте?','Библиотека находится здесь, за правой дверью — тренировочный зал. Северный проход ведёт в крипту. Каждый сундук и разговор можно восстановить во вкладке «Тест».')}},
{label:'Расскажи о крипте?',fn:()=>recordReply('Расскажи о крипте?','В крипте есть второй алтарь, архив и сундук. Возвращайтесь через дверь у южной стены: отряд перейдёт вместе с вами.')},
{label:'Попросить довериться · убеждение d20',fn:persuade},
{label:'У меня нет времени',fn:()=>{g().tell('Вы прервали разговор с Эллен. К её вопросам можно вернуться позже.');g().render();closeDialogue()}}]);}
function persuade(){const s=g().state;if(s.persuasionAttempted){dialogueLine(s.secretKnown?'Я уже сказала вам о тайнике за книгами. Больше мне добавить нечего.':'Я пока не готова доверять вам больше. Но основные ответы я уже дала.',[{label:'Другой вопрос',fn:openKeeper},{label:'Закончить',fn:closeDialogue}]);return}const check=DND.skill(g().active(),'persuasion',12,s.level,s.advantage||0),n=check.natural,bonus=check.bonus,ok=check.success;g().report(check.text);s.persuasionAttempted=true;s.secretKnown=ok;if(ok)s.xp+=10;const response=ok?'Я доверюсь вам. За книгами у настоятеля спрятан список имён. Найдите его, когда доберётесь до монастыря.':'Простите. Я слишком мало вас знаю, чтобы рисковать чужими жизнями.';g().tell('Убеждение: d20 '+n+' + '+bonus+' против 12 — '+(ok?'успех. +10 опыта.':'неудача.')+' Эллен: «'+response+'»');g().render();dialogueLine('d20 '+n+' + '+bonus+' против 12. '+response,[{label:'Вернуться к вопросам',fn:openKeeper},{label:'Закончить разговор',fn:closeDialogue}])}
function openNarrator(){switchTab('map');dialogueLine('Это личный визуальный полигон. Эллен ждёт в библиотеке, манекены — в правом крыле. Предметы и бой можно сбрасывать.',[{label:'Показать Эллен',fn:()=>{closeDialogue();g().test('npc');window.camera?.center(g().active(),true)}},{label:'Проверить диалог',fn:openKeeper},{label:'Как управлять?',fn:()=>g().help()},{label:'Хроника проверок',fn:()=>g().journal()}],'Ведущий',false)}
function openObject(p){dialogueLine(p.type==='books'?'На полках стоят книги по алхимии и старые путевые заметки. Среди страниц лежит закладка Эллен.':'На столе раскрыт журнал хранительницы. Рядом остывает воск от свечи.',[{label:'Прочитать заметку',fn:()=>dialogueLine('«Свет не должен ослеплять путника. Тень должна следовать за вещью, а шаг — приводить точно к её месту».',[{label:'Закрыть',fn:closeDialogue}],p.name,false)},{label:'Закрыть',fn:closeDialogue}],p.name,false)}
window.openObjectDialogue=openObject;

window.initViews=()=>{for(const name of['map','hero','bag','test'])$('tab-'+name).onclick=()=>switchTab(name);$('hero-prev').onclick=()=>selectHero(-1);$('hero-next').onclick=()=>selectHero(1);$('level-up').onclick=levelUp;$('dialogue-close').onclick=closeDialogue;renderViews()};
window.renderViews=renderViews;window.drawKeeper=drawKeeper;window.openKeeperDialogue=openKeeper;window.openNarratorDialogue=openNarrator;window.closeDialogue=closeDialogue;
keeper.onload=()=>{const c=document.createElement('canvas');c.width=keeper.width;c.height=keeper.height;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(keeper,0,0);keeperRects=[];for(let i=0;i<2;i++){const sx=i*keeper.width/2,w=Math.floor(keeper.width/2),h=keeper.height,a=cx.getImageData(sx,0,w,h).data;let l=w,t=h,r=0,b=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(a[(y*w+x)*4+3]>40){l=Math.min(l,x);t=Math.min(t,y);r=Math.max(r,x);b=Math.max(b,y)}keeperRects.push({sx:sx+l,sy:t,w:r-l+1,h:b-t+1})}g()?.render()};keeper.src='assets/keeper.png';
window.viewsDebug={switchTab,openKeeper,openNarrator,persuade,levelUp,get tab(){return tab}};
})();
